#!/usr/bin/env bash
# GENERATED by tools/landed_parent/lp.py: lockstep bench forest_top (flat) vs forest_top_lp + mutants [1, 2, 4] + region audit.
# Run on the FLEET (ot-run), never on localhost.  Exit 0 iff MUT 0 PASSES, every mutant FAILS and the audit PASSES.
#   bash results/arch/safe_qw_slice_w_1019/reset_forest/generator_fixture/forest_top_lp_bench.sh OUTDIR        (SIM=iverilog default | verilator; VERILATOR, VL_JOBS, VL_EXTRA,
#   MUTS="0 1 .." optional overrides)
set -u
cd "${LP_ROOT:-$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null || (cd "$(dirname "$0")/../../../../.." && pwd))}"
OUT=${1:-lp_bench_out}; mkdir -p "$OUT"; SIM=${SIM:-iverilog}; rc=0
SRCS="results/arch/safe_qw_slice_w_1019/reset_forest/generator_fixture/top.sv results/arch/safe_qw_slice_w_1019/reset_forest/generator_fixture/child.sv rtl/common/landed_parent/ot_pl_land.sv rtl/common/landed_parent/ot_pl_land_field_copies.sv rtl/common/landed_parent/ot_pl_land_reset_forest.sv results/arch/safe_qw_slice_w_1019/reset_forest/generator_fixture/forest_top_lp.sv results/arch/safe_qw_slice_w_1019/reset_forest/generator_fixture/tb_forest_top_lp.sv"
python3 tools/landed_parent/lp.py audit results/arch/safe_qw_slice_w_1019/reset_forest/generator_fixture/spec.json > "$OUT/audit.log" 2>&1 && echo "AUDIT PASS" || { echo "AUDIT FAIL"; rc=1; }
python3 tools/landed_parent/lp.py audit results/arch/safe_qw_slice_w_1019/reset_forest/generator_fixture/spec.json --rtl "$OUT/unland.sv" --make-unland > "$OUT/audit_unland.log" 2>&1 \
  && { echo "AUDIT-UNLAND PASSED (should FAIL)"; rc=1; } || echo "AUDIT-UNLAND FAIL (expected)"
for m in ${MUTS:-0 1 2 4}; do
  if [ "$SIM" = verilator ]; then
    ${VERILATOR:-verilator} --binary -j ${VL_JOBS:-8} -Wno-fatal ${VL_EXTRA:-} --top-module tb_forest_top_lp -GMUT=$m  $SRCS -Mdir "$OUT/obj$m" > "$OUT/build_$m.log" 2>&1 \
      && "$OUT/obj$m/Vtb_forest_top_lp" > "$OUT/mut$m.log" 2>&1
  else
    iverilog -g2012 -o "$OUT/sim$m" -s tb_forest_top_lp -Ptb_forest_top_lp.MUT=$m  $SRCS > "$OUT/build_$m.log" 2>&1 \
      && vvp -n "$OUT/sim$m" > "$OUT/mut$m.log" 2>&1
  fi
  r=$(grep -o 'LP_LOCKSTEP [A-Z]*' "$OUT/mut$m.log" 2>/dev/null | head -1)
  echo "MUT $m: ${r:-NO_RESULT (see $OUT/build_$m.log)}"
  if [ $m -eq 0 ]; then [ "$r" = "LP_LOCKSTEP PASS" ] || rc=1; else [ "$r" = "LP_LOCKSTEP FAIL" ] || rc=1; fi
done
echo "BENCH_EXIT $rc"; exit $rc
